INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('51f560fe-cc0b-494f-8fba-eaaa31272c60','ea72c86d-dd82-43af-b15b-8f839b420923','Tsunami : Gelombang',false,1,now()+interval '10 second'+interval '40 millisecond',now());
INSERT INTO questions (id,test_id,description,image,explanation,sub_material_code,created_at,updated_at) VALUES ('f9e8794a-ff67-47d2-a4df-956bf5ed1035','7b176b69-5046-4a81-a6b0-85ca16fde19f','Dalam hukum pidana, istilah “restitusi” bermakna ....','','DIKETAHUI:
- Istilah yang diuji: restitusi (tanpa konteks kalimat).
- Pilihan berisi definisi istilah yang mirip bentuk atau maknanya: kompensasi, restitusi, retribusi, rehabilitasi, restorasi.

DITANYAKAN:
Definisi yang tepat untuk restitusi dalam hukum pidana.

JAWAB:
1. Cari makna KBBI. Restitusi berarti ‘ganti kerugian; pembayaran kembali’. Dalam bidang hukum, restitusi adalah ganti rugi yang diberikan kepada korban.
2. Pertajam dengan pengertian dalam perundang-undangan perlindungan saksi dan korban (UU No. 31 Tahun 2014). Restitusi adalah ganti kerugian yang diberikan kepada korban atau keluarganya oleh PELAKU atau PIHAK KETIGA.
3. Bedakan dengan kompensasi. Dalam undang-undang yang sama, kompensasi adalah ganti kerugian yang diberikan oleh NEGARA karena pelaku tidak mampu memberikan ganti kerugian sepenuhnya. Pembedanya adalah SIAPA YANG MEMBAYAR.
4. Pilihan (B) memuat ganti kerugian kepada korban yang dibebankan kepada pelaku atau pihak ketiga. Definisi ini tepat.
Jadi, jawaban yang tepat adalah (B) ganti kerugian kepada korban atau keluarganya yang dibebankan kepada pelaku atau pihak ketiga. Restitusi dibayar oleh pelaku atau pihak ketiga, sedangkan kompensasi dibayar oleh negara.
Mengapa opsi lain kurang tepat:
- (A) Ini definisi kompensasi, karena pembayarnya negara. Pengecoh terkuat sebab sama-sama ganti rugi untuk korban.
- (C) Ini definisi retribusi. Bentuk katanya mirip (re-tribusi), tetapi istilah ini berasal dari bidang keuangan daerah.
- (D) Ini definisi rehabilitasi, yaitu pemulihan nama baik, bukan ganti rugi berupa uang.
- (E) Ini definisi restorasi, yaitu pengembalian ke keadaan semula untuk bangunan atau benda.','VRB-02',now()+interval '11 second',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('057b560e-edd1-464d-9d50-14e602ea4e70','f9e8794a-ff67-47d2-a4df-956bf5ed1035','ganti kerugian kepada korban yang diberikan oleh negara karena pelaku tidak mampu menanggungnya sepenuhnya',false,1,now()+interval '11 second'+interval '0 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('6adab00f-5b35-4920-880c-a0420bfd9756','f9e8794a-ff67-47d2-a4df-956bf5ed1035','ganti kerugian kepada korban atau keluarganya yang dibebankan kepada pelaku atau pihak ketiga',true,1,now()+interval '11 second'+interval '10 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('9f03edef-d4b3-4cd1-9faa-151290ebb12c','f9e8794a-ff67-47d2-a4df-956bf5ed1035','pungutan daerah sebagai pembayaran atas jasa atau pemberian izin tertentu',false,1,now()+interval '11 second'+interval '20 millisecond',now());
