INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('e15f1371-f4c0-49a6-a54a-90b2c259181a','6e8344e6-4c78-45ed-afc2-dd434e5e654c','analitis',false,1,now()+interval '17 second'+interval '30 millisecond',now());
