INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('8b6a879f-4b09-40a4-b7c1-cea9aae887c6','d543672d-b854-421a-9337-144c897e41f5','Dimas bukan anggota Gegana dan bukan penjinak bom.',true,1,now()+interval '21 second'+interval '30 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('d9b04fd6-cb06-4608-8522-74eac8b722b5','d543672d-b854-421a-9337-144c897e41f5','Semua personel yang bukan anggota Gegana memiliki riwayat cedera lutut berat.',false,1,now()+interval '21 second'+interval '40 millisecond',now());
INSERT INTO questions (id,test_id,description,image,explanation,sub_material_code,created_at,updated_at) VALUES ('915526bb-b3d1-4ea9-a991-ecc084d8327c','7b176b69-5046-4a81-a6b0-85ca16fde19f','Diketahui premis-premis berikut.
(1) Sebagian anggota Ditpolairud adalah penyelam bersertifikat.
(2) Tidak ada penyelam bersertifikat yang memiliki riwayat gangguan telinga.
(3) Semua personel yang memiliki riwayat gangguan telinga dibebastugaskan dari operasi bawah air.

Simpulan yang pasti benar adalah ....','','DIKETAHUI:
- A = anggota Ditpolairud; P = penyelam bersertifikat; T = memiliki riwayat gangguan telinga; B = dibebastugaskan dari operasi bawah air.
- (1) A∩P tidak kosong; (2) P∩T kosong; (3) T ⊆ B.

DITANYAKAN:
Simpulan yang pasti benar.

JAWAB:
1. Ambil w dari (1): w ∈ A dan w ∈ P.
2. Dari (2): w ∈ P, maka w ∉ T. Jadi "Sebagian A bukan T" pasti benar.
3. Perhatikan premis (3) T → B. Dari w ∉ T tidak dapat disimpulkan w ∉ B; itu penolakan anteseden. Orang dapat dibebastugaskan karena alasan lain.
4. Diagram tandingan: B dibuat sangat luas sehingga mencakup seluruh A (termasuk w). Semua premis tetap terpenuhi, sehingga klaim apa pun tentang "tidak dibebastugaskan" gugur.
5. Hanya simpulan pada langkah 2 yang bertahan di semua diagram sah.
Jadi, jawaban yang tepat adalah (A) Sebagian anggota Ditpolairud tidak memiliki riwayat gangguan telinga.
Mengapa opsi lain kurang tepat:
- (B) Penolakan anteseden: dari "tidak punya gangguan telinga" tidak dapat disimpulkan "tidak dibebastugaskan", karena B bisa lebih luas daripada T.
- (C) Sesat pikir yang sama dengan (B), bahkan digeneralisasi ke semua penyelam bersertifikat.
- (D) Premis tidak menjamin ada anggota Ditpolairud yang memiliki riwayat gangguan telinga; T bahkan bisa kosong.
- (E) Tidak ada premis yang mengatur anggota non-penyelam; mereka boleh punya riwayat gangguan telinga atau tidak.','VRB-09',now()+interval '22 second',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('6d5693b1-89ce-45fb-882b-652f1af9da38','915526bb-b3d1-4ea9-a991-ecc084d8327c','Sebagian anggota Ditpolairud tidak memiliki riwayat gangguan telinga.',true,1,now()+interval '22 second'+interval '0 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('6db25acf-cad4-482c-a021-99a82378388f','915526bb-b3d1-4ea9-a991-ecc084d8327c','Sebagian anggota Ditpolairud tidak dibebastugaskan dari operasi bawah air.',false,1,now()+interval '22 second'+interval '10 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('e1bcd482-027c-4c26-8fc7-72a552517b59','915526bb-b3d1-4ea9-a991-ecc084d8327c','Tidak ada penyelam bersertifikat yang dibebastugaskan dari operasi bawah air.',false,1,now()+interval '22 second'+interval '20 millisecond',now());
