INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('2567ebea-33c8-4b4a-9582-87f48dca80be','b7e10367-67e5-4b76-b196-91441634e969','Bripka Dodi bertugas di pos pengamanan, tetapi Aipda Joko tidak bertugas di posko kesehatan.',false,1,now()+interval '25 second'+interval '20 millisecond',now());
