INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('b45efdf7-9ba0-48ce-b3a5-f714e192ba8e','76212437-563b-416b-972f-1ad6867a2125','31 dan 148',false,1,now()+interval '55 second'+interval '40 millisecond',now());
INSERT INTO questions (id,test_id,description,image,explanation,sub_material_code,created_at,updated_at) VALUES ('cea5e920-dfae-416c-8b20-c65735b7fc4c','7b176b69-5046-4a81-a6b0-85ca16fde19f','Perhatikan deret berikut.
7, 10, 16, 25, 37, 52, ...
Jika pola deret tetap, suku pertama yang nilainya lebih dari 1.000 adalah suku ke- ....','','DIKETAHUI:
- Deret: 7, 10, 16, 25, 37, 52, ...
- Batas: lebih dari 1.000.

DITANYAKAN:
Nomor suku pertama yang nilainya lebih dari 1.000.

JAWAB:
1. Selisih tingkat satu: 3, 6, 9, 12, 15 (kelipatan 3).
   Selisih tingkat dua: 3, 3, 3, 3 (tetap).
2. Rumus umum: Un = U1 + jumlah (n − 1) selisih pertama
   = 7 + 3 × (1 + 2 + ... + (n − 1))
   = 7 + 3 × n(n − 1)/2.
   Uji: U4 = 7 + 3 × 6 = 25; U6 = 7 + 3 × 15 = 52 (sesuai).
3. Syarat: 7 + 3n(n − 1)/2 > 1.000 → 3n(n − 1)/2 > 993 → n(n − 1) > 662.
4. Coba di sekitar √662 ≈ 25,7:
   n = 26: 26 × 25 = 650 < 662 (belum)
   n = 27: 27 × 26 = 702 > 662 (sudah)
5. Cek nilai: U26 = 7 + 3 × 325 = 982 dan U27 = 7 + 3 × 351 = 1.060.
   Jadi suku pertama yang lebih dari 1.000 adalah suku ke-27.
Jadi, jawaban yang tepat adalah (A) 27.
Mengapa opsi lain kurang tepat:
- (B) 26: suku ke-26 = 7 + 3 × (26 × 25 : 2) = 7 + 975 = 982, belum lebih dari 1.000.
- (C) 28: suku ke-28 = 1.141 memang lebih dari 1.000, tetapi suku ke-27 sudah lebih dulu melampauinya.
- (D) 25: suku ke-25 = 7 + 3 × 300 = 907, belum lebih dari 1.000.
- (E) 24: suku ke-24 = 7 + 3 × 276 = 835, masih jauh di bawah 1.000.','NUM-11',now()+interval '56 second',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('ccddf2db-e305-4fd9-84a9-a5f27fde22f6','cea5e920-dfae-416c-8b20-c65735b7fc4c','27',true,1,now()+interval '56 second'+interval '0 millisecond',now());
