INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('44c0b1aa-e2d9-405f-b06d-17180f6d917f','c91af809-cb7c-4530-b021-48f081604d18','49 dan 147',false,1,now()+interval '58 second'+interval '40 millisecond',now());
INSERT INTO questions (id,test_id,description,image,explanation,sub_material_code,created_at,updated_at) VALUES ('a844a8c4-4893-45d7-9062-bed60cfecf6f','7b176b69-5046-4a81-a6b0-85ca16fde19f','Perhatikan deret berikut.
1, 81, 2, 27, 4, 9, 7, 3, 11, ..., ...
Dua bilangan berikutnya adalah ....','','DIKETAHUI:
- Deret 9 suku: 1, 81, 2, 27, 4, 9, 7, 3, 11.
- Suku kecil dan besar bergantian, tanda dua larik berselang.

DITANYAKAN:
Suku ke-10 dan ke-11.

JAWAB:
1. Pisahkan dua larik.
   Larik ganjil (suku ke-1, 3, 5, 7, 9): 1, 2, 4, 7, 11
   Larik genap (suku ke-2, 4, 6, 8): 81, 27, 9, 3
2. Larik ganjil (bertingkat):
   selisih tingkat satu: +1, +2, +3, +4
   selisih tingkat dua: +1 (tetap), berikutnya +5 → 11 + 5 = 16.
3. Larik genap (geometri):
   rasio 27 : 81 = 1/3; 9 : 27 = 1/3; 3 : 9 = 1/3 (tetap)
   berikutnya 3 × 1/3 = 1.
4. Urutan: suku ke-9 (11) milik larik ganjil, maka suku ke-10 milik larik genap = 1 dan suku ke-11 milik larik ganjil = 16.
5. Deret lengkap: 1, 81, 2, 27, 4, 9, 7, 3, 11, 1, 16.
Jadi, jawaban yang tepat adalah (D) 1 dan 16.
Mengapa opsi lain kurang tepat:
- (A) 1 dan 15: larik ganjil memakai selisih +4 diulang (11 + 4 = 15), padahal selisihnya naik 1 setiap langkah sehingga berikutnya +5.
- (B) 0 dan 16: larik genap dianggap dikurangi 3 (3 − 3 = 0). Larik 81, 27, 9, 3 berpola dibagi 3, bukan dikurangi bilangan tetap.
- (C) 16 dan 1: nilainya benar tetapi urutannya tertukar. Suku ke-10 milik larik genap (1), baru suku ke-11 milik larik ganjil (16).
- (E) 1 dan 17: larik ganjil memakai selisih +6 (melompati +5), sehingga 11 + 6 = 17.','NUM-12',now()+interval '59 second',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('f311457c-4b03-402d-9c01-fe753d036561','a844a8c4-4893-45d7-9062-bed60cfecf6f','1 dan 15',false,1,now()+interval '59 second'+interval '0 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('09e22cb0-db03-4e5f-969e-f8cb95fa0ff7','a844a8c4-4893-45d7-9062-bed60cfecf6f','0 dan 16',false,1,now()+interval '59 second'+interval '10 millisecond',now());
