INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('c7681fb9-f90e-4bab-bd47-8f6d2667e541','edcdf9f7-0f8e-40a0-9b5a-398c4f72b861','F dan 63',false,1,now()+interval '65 second'+interval '40 millisecond',now());
INSERT INTO questions (id,test_id,description,image,explanation,sub_material_code,created_at,updated_at) VALUES ('8eb6e329-6dba-437e-a3f7-cd4313b3fe4f','7b176b69-5046-4a81-a6b0-85ca16fde19f','Hasil dari
4.998 × 5.002 − 4.997 × 5.003
adalah ....','','DIKETAHUI:
- Bentuk: 4.998 × 5.002 − 4.997 × 5.003.
- Kedua perkalian berbentuk (5.000 − k)(5.000 + k).

DITANYAKAN:
Nilai bentuk tersebut.

JAWAB:
1. Gunakan (a − b)(a + b) = a² − b² dengan a = 5.000.
2. 4.998 × 5.002 = (5.000 − 2)(5.000 + 2) = 5.000² − 2² = 25.000.000 − 4 = 24.999.996.
3. 4.997 × 5.003 = (5.000 − 3)(5.000 + 3) = 5.000² − 3² = 25.000.000 − 9 = 24.999.991.
4. Selisih = 24.999.996 − 24.999.991 = 5.
   Cara cepat: (5.000² − 4) − (5.000² − 9) = −4 + 9 = 5.
5. Uji akal sehat: hasil kali dua bilangan berjumlah tetap (10.000) makin kecil bila keduanya makin berjauhan, sehingga 4.997 × 5.003 < 4.998 × 5.002 dan hasilnya positif.
Jadi, jawaban yang tepat adalah (C) 5.
Mengapa opsi lain kurang tepat:
- (A) −5: tanda terbalik: menganggap 4.997 × 5.003 lebih besar karena faktornya lebih menyebar. Justru semakin jauh dari 5.000, hasil kalinya semakin kecil.
- (B) 1: hanya mengurangkan selisih jaraknya: 3 − 2 = 1, padahal yang berkurang adalah kuadrat jarak (9 − 4).
- (D) 13: kuadrat jarak dijumlahkan: 4 + 9 = 13, padahal keduanya dikurangkan dari 5.000² sehingga hasilnya −4 − (−9).
- (E) 9: hanya menghitung 3² dari perkalian kedua dan melupakan −2² pada perkalian pertama.','NUM-28',now()+interval '66 second',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('161892e2-4f99-4f6d-8988-dcfaaafce786','8eb6e329-6dba-437e-a3f7-cd4313b3fe4f','−5',false,1,now()+interval '66 second'+interval '0 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('66d0f028-2781-44fe-a219-78f4142e8d1d','8eb6e329-6dba-437e-a3f7-cd4313b3fe4f','1',false,1,now()+interval '66 second'+interval '10 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('de47d807-1a90-40c6-880b-ad86f52c430a','8eb6e329-6dba-437e-a3f7-cd4313b3fe4f','5',true,1,now()+interval '66 second'+interval '20 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('f27c8bf9-f180-4285-b285-8b1b75b88972','8eb6e329-6dba-437e-a3f7-cd4313b3fe4f','13',false,1,now()+interval '66 second'+interval '30 millisecond',now());
