INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('0a4fc046-7bf7-4690-91ce-5614c1554ebd','04425083-27e0-4eb1-bcf9-f848f094ee3a','2.440',true,1,now()+interval '67 second'+interval '40 millisecond',now());
INSERT INTO questions (id,test_id,description,image,explanation,sub_material_code,created_at,updated_at) VALUES ('99f9fba2-03ff-4b26-9528-4af976adb5f4','7b176b69-5046-4a81-a6b0-85ca16fde19f','Sebuah mesin fotokopi di bagian administrasi Polres dapat mencetak 1.200 lembar dalam 16 menit. Sebanyak 45 berkas laporan, masing-masing 48 halaman, harus digandakan satu kali secara bolak-balik (setiap lembar memuat 2 halaman). Jika pekerjaan dibagi rata pada 2 mesin identik yang bekerja bersamaan, waktu yang diperlukan adalah ....','','DIKETAHUI:
- 1 mesin: 1.200 lembar dalam 16 menit.
- 45 berkas × 48 halaman, dicetak bolak-balik (2 halaman per lembar).
- 2 mesin identik bekerja bersamaan.

DITANYAKAN:
Waktu penggandaan.

JAWAB:
1. Kecepatan 1 mesin = 1.200 ÷ 16 = 75 lembar/menit; 2 mesin = 150 lembar/menit.
2. Banyak halaman = 45 × 48 = 2.160 halaman.
3. Banyak lembar (bolak-balik) = 2.160 ÷ 2 = 1.080 lembar.
4. Waktu = 1.080 ÷ 150 = 7,2 menit.
5. 0,2 menit = 0,2 × 60 = 12 detik, jadi waktunya 7 menit 12 detik.
Jadi, jawaban yang tepat adalah (B) 7 menit 12 detik.
Mengapa opsi lain kurang tepat:
- (A) 3 menit 36 detik: Banyak lembar dibagi 2 dua kali (540 lembar), seolah-olah bolak-balik mengurangi lembar dua kali. 1.080 lembar sudah memperhitungkan bolak-balik.
- (C) 7 menit 20 detik: 7,2 menit dibaca 7 menit 20 detik. Padahal 0,2 menit = 0,2 × 60 = 12 detik.
- (D) 14 menit 24 detik: Salah satu faktor terlewat: tidak dicetak bolak-balik (2.160 ÷ 150) atau hanya memakai satu mesin (1.080 ÷ 75); keduanya menghasilkan 14,4 menit.
- (E) 28 menit 48 detik: 2.160 ÷ 75 = 28,8 menit. Bolak-balik dan dua mesin sama-sama tidak diperhitungkan.','NUM-15',now()+interval '68 second',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('a99cc267-5ce9-4f01-a523-d552e054ab11','99f9fba2-03ff-4b26-9528-4af976adb5f4','3 menit 36 detik',false,1,now()+interval '68 second'+interval '0 millisecond',now());
