INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('f683cd4b-e876-43f9-9ef6-2ad3064ad978','63f6b58b-7c09-4ca0-97ad-c4b5d9875357','C',true,1,now()+interval '97 second'+interval '20 millisecond',now());
