INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('b68d2d60-4032-4e22-96fa-a267b07025b1','607296da-6657-4a14-a430-d4c52823ce0d','Berhenti mengikuti akun itu dan membatalkan semua tanda suka yang pernah Anda berikan agar jejak digital Anda bersih dan tidak menimbulkan salah paham ketika diperiksa saat seleksi.',true,4,now()+interval '69 second'+interval '30 millisecond',now());
