INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('96b7d57f-8fdf-4171-8d78-01783497793d','3fa90a86-74ec-4608-bb08-028387cd2c98','Sebagian laporan yang masuk melalui layanan 110 tidak ditindaklanjuti dalam waktu satu jam.',false,1,now()+interval '33 second'+interval '20 millisecond',now());
