INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('585644e4-ac70-4bd2-a578-1d1f305377f1','6ee37f11-e7d9-471c-ae14-3cf8a5391415','1.983',false,1,now()+interval '66 second'+interval '40 millisecond',now());
INSERT INTO questions (id,test_id,description,image,explanation,sub_material_code,created_at,updated_at) VALUES ('d6386d49-1bcc-4afd-84c6-6e4a5d7a6ae7','6a5458fd-d2b4-47cc-86d0-693bc39b525d','Hasil dari
1.003² − 997² + 49 × 51 − 50²
adalah ....','','DIKETAHUI:
- Bentuk: 1.003² − 997² + 49 × 51 − 50².
- Bilangan dekat dengan 1.000 dan 50, cocok untuk bentuk selisih kuadrat a² − b² = (a − b)(a + b).

DITANYAKAN:
Nilai bentuk tersebut.

JAWAB:
1. 1.003² − 997² = (1.003 − 997)(1.003 + 997) = 6 × 2.000 = 12.000.
2. 49 × 51 = (50 − 1)(50 + 1) = 50² − 1² = 2.500 − 1 = 2.499.
3. 49 × 51 − 50² = 2.499 − 2.500 = −1.
4. Hasil = 12.000 + (−1) = 11.999.
5. Cek cara panjang: 1.003² = 1.006.009; 997² = 994.009; selisihnya 12.000. 49 × 51 = 2.499; 50² = 2.500. Total 12.000 + 2.499 − 2.500 = 11.999 (sesuai).
Jadi, jawaban yang tepat adalah (B) 11.999.
Mengapa opsi lain kurang tepat:
- (A) 12.001: 49 × 51 dianggap 50² + 1, padahal (50 − 1)(50 + 1) = 50² − 1.
- (C) 12.000: 49 × 51 dianggap sama dengan 50², sehingga selisih −1 hilang.
- (D) 11.987: 1.003² − 997² dihitung 6 × 1.998 = 11.988 (salah menjumlah 1.003 + 997), lalu ditambah −1.
- (E) 35: 1.003² − 997² dikira sama dengan (1.003 − 997)² = 36, lalu 36 − 1 = 35. Selisih dua kuadrat bukan kuadrat dari selisih.','NUM-28',now()+interval '67 second',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('23df06ff-44d9-4204-a112-64928139746b','d6386d49-1bcc-4afd-84c6-6e4a5d7a6ae7','12.001',false,1,now()+interval '67 second'+interval '0 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('85029532-bb8d-463b-b371-66b2b0641813','d6386d49-1bcc-4afd-84c6-6e4a5d7a6ae7','11.999',true,1,now()+interval '67 second'+interval '10 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('c6a382d4-c88e-4c29-aeb2-29a38fa32e3e','d6386d49-1bcc-4afd-84c6-6e4a5d7a6ae7','12.000',false,1,now()+interval '67 second'+interval '20 millisecond',now());
