INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('b44bb5f2-1cfb-41b2-a092-2db321ad6f65','d6386d49-1bcc-4afd-84c6-6e4a5d7a6ae7','35',false,1,now()+interval '67 second'+interval '40 millisecond',now());
INSERT INTO questions (id,test_id,description,image,explanation,sub_material_code,created_at,updated_at) VALUES ('e6855751-0f9d-4c46-a31c-f9165c291526','6a5458fd-d2b4-47cc-86d0-693bc39b525d','Persediaan ransum di sebuah posko pengamanan bencana cukup untuk 60 personel selama 30 hari. Setelah persediaan dipakai 6 hari, datang 20 personel tambahan. Empat hari kemudian, 10 personel ditarik kembali ke markas. Jika setiap personel menghabiskan jatah yang sama setiap hari, sisa persediaan sejak penarikan itu cukup untuk ... hari lagi.','','DIKETAHUI:
- Persediaan awal cukup untuk 60 personel × 30 hari.
- Hari ke-1 sampai ke-6: 60 personel.
- 4 hari berikutnya: 60 + 20 = 80 personel.
- Setelah itu 10 personel ditarik: 80 − 10 = 70 personel.

DITANYAKAN:
Lama sisa persediaan untuk 70 personel.

JAWAB:
1. Nyatakan persediaan dalam satuan jatah (personel-hari): 60 × 30 = 1.800 jatah.
2. Pemakaian 6 hari pertama: 60 × 6 = 360 jatah. Sisa = 1.800 − 360 = 1.440 jatah.
3. Pemakaian 4 hari berikutnya oleh 80 personel: 80 × 4 = 320 jatah. Sisa = 1.440 − 320 = 1.120 jatah.
4. Sisa untuk 70 personel: 1.120 ÷ 70 = 16 hari.
5. Uji: 360 + 320 + (70 × 16) = 360 + 320 + 1.120 = 1.800 jatah, sama dengan persediaan awal.
Jadi, jawaban yang tepat adalah (B) 16.
Mengapa opsi lain kurang tepat:
- (A) 14: 1.120 ÷ 80 = 14 hari. Hasil ini lupa bahwa 10 personel sudah ditarik, sehingga yang makan tinggal 70 orang.
- (C) 18: Ini sisa hari tepat ketika 20 personel datang (1.440 ÷ 80 = 18). Hitungan berhenti sebelum memperhitungkan 4 hari pemakaian dan penarikan personel.
- (D) 20: 30 − 6 − 4 = 20 hari. Hasil ini mengurangi hari saja dan mengabaikan perubahan jumlah personel, padahal banyak personel dan lama persediaan berbalik nilai.
- (E) 24: 1.440 ÷ 60 = 24 hari, yaitu sisa persediaan jika tidak ada perubahan personel setelah hari ke-6.','NUM-15',now()+interval '68 second',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('e77f6669-e681-4c5f-9786-5833f6def06b','e6855751-0f9d-4c46-a31c-f9165c291526','14',false,1,now()+interval '68 second'+interval '0 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('7d781d2a-23bb-4016-b9ad-a3210a6ff20e','e6855751-0f9d-4c46-a31c-f9165c291526','16',true,1,now()+interval '68 second'+interval '10 millisecond',now());
