INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('66ec1ea7-3c9a-4b9e-8f0a-81a9fbeac3ba','bbf36787-c20c-4eda-95b2-18999f2a5607','19,2 liter',true,1,now()+interval '69 second'+interval '20 millisecond',now());
