INSERT INTO questions (id,test_id,description,image,explanation,sub_material_code,created_at,updated_at) VALUES ('6d83c9e9-5278-40a0-8c73-4e85b22b8716','6a5458fd-d2b4-47cc-86d0-693bc39b525d','Posko bantuan menerima 25 karung beras dengan bruto seluruhnya 1.275 kg. Tara (berat karung) adalah 4% dari bruto. Seluruh beras netto dikemas ulang menjadi paket 5 kg untuk warga. Banyak paket utuh yang dapat dibuat dan sisa beras yang tidak cukup untuk satu paket adalah ....','','DIKETAHUI:
- Bruto = 1.275 kg (25 karung).
- Tara = 4% dari bruto.
- Paket = 5 kg.

DITANYAKAN:
Banyak paket utuh dan sisa beras.

JAWAB:
1. Tara = 4% × 1.275 = 51 kg.
2. Netto = bruto − tara = 1.275 − 51 = 1.224 kg (atau 96% × 1.275 = 1.224 kg).
3. Banyak paket: 1.224 ÷ 5 = 244 sisa 4, karena 244 × 5 = 1.220 kg.
4. Sisa beras = 1.224 − 1.220 = 4 kg (kurang dari 5 kg, tidak cukup untuk satu paket).
5. Jadi diperoleh 244 paket utuh dengan sisa 4 kg.
Jadi, jawaban yang tepat adalah (D) 244 paket, sisa 4 kg.
Mengapa opsi lain kurang tepat:
- (A) 255 paket, sisa 0 kg: Bruto langsung dibagi 5 (1.275 ÷ 5) tanpa mengurangi tara. Berat karung tidak bisa dibagikan sebagai beras.
- (B) 254 paket, sisa 1 kg: Tara 4% dianggap 4 kg saja untuk seluruh karung: 1.275 − 4 = 1.271 kg → 254 paket, sisa 1 kg.
- (C) 244 paket, sisa 0,8 kg: 1.224 ÷ 5 = 244,8; angka 0,8 itu bagian paket, bukan kilogram. 0,8 paket = 0,8 × 5 = 4 kg.
- (E) 235 paket, sisa 0 kg: Tara dianggap 4 kg per karung: 25 × 4 = 100 kg, netto 1.175 kg → 235 paket. Soal menyebut tara 4% dari bruto, bukan 4 kg per karung.','NUM-19',now()+interval '73 second',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('e4e80dbd-8349-4d45-8c79-5095867c7f1b','6d83c9e9-5278-40a0-8c73-4e85b22b8716','255 paket, sisa 0 kg',false,1,now()+interval '73 second'+interval '0 millisecond',now());
INSERT INTO answers (id,question_id,description,is_correct,point,created_at,updated_at) VALUES ('0149656e-8c29-4aa2-94e5-e0a611ba0553','6d83c9e9-5278-40a0-8c73-4e85b22b8716','254 paket, sisa 1 kg',false,1,now()+interval '73 second'+interval '10 millisecond',now());
